async function mutate(path,data={}){
 if(busy)return;busy=true;
 const spin=selectedGame==='slots'&&(path==='game/start'||data.action==='spin'),animate=spin&&matchMedia('(prefers-reduced-motion: no-preference)').matches;
 if(animate){slotSpinning=true;renderGame();}$('#main').classList.add('loading');
 try{const [response]=await Promise.all([api(path,{...data,requestId:crypto.randomUUID(),version:snapshot.version}),pause(animate?1200:0)]);slotSpinning=false;slotLanding=animate;apply(response);beep();render();if(animate)await pause(1100);if(path==='game/start'||path==='game/action')notifyRoundResult(response.game,data.action);return true;}
 catch(e){slotSpinning=false;slotLanding=false;toast(e.message);try{apply(await api('me'));render()}catch{if(spin)renderGame();}}
 finally{slotSpinning=false;slotLanding=false;busy=false;$('#main').classList.remove('loading');}
}
function art(type,large=false){let content='';if(type==='roulette'){content=`<g transform="translate(140 90)"><circle r="72" fill="#172a20" stroke="#c1ad78" stroke-width="5"/>${Array.from({length:24},(_,i)=>`<path d="M0 0 L${Math.cos(i*Math.PI/12)*68} ${Math.sin(i*Math.PI/12)*68} A68 68 0 0 1 ${Math.cos((i+1)*Math.PI/12)*68} ${Math.sin((i+1)*Math.PI/12)*68}Z" fill="${i%2?'#a05545':'#3c5a43'}" stroke="#cebe90" stroke-width=".5"/>`).join('')}<circle r="43" fill="#a59260"/><circle r="36" fill="#2e4935" stroke="#e4d7ae"/><path d="M-27 0H27M0-27V27" stroke="#d5c38f" stroke-width="4"/><circle r="8" fill="#e5d7ad"/><circle cx="25" cy="-55" r="4" fill="#fff1d0"/></g>`}else if(['blackjack','russian','threecard','holdem','baccarat'].includes(type)){content=`<g transform="translate(85 28) rotate(-15 40 60)"><rect width="74" height="112" rx="5" fill="#e8e2cf"/><text x="8" y="25" fill="#354937" font-family="Georgia" font-size="24">A</text><text x="37" y="80" fill="#354937" text-anchor="middle" font-size="50">♠</text></g><g transform="translate(142 32) rotate(13 40 60)"><rect width="74" height="112" rx="5" fill="#f1ecdb"/><text x="8" y="25" fill="#a45443" font-family="Georgia" font-size="24">${type==='blackjack'?'K':'A'}</text><text x="37" y="80" fill="#a45443" text-anchor="middle" font-size="50">♥</text></g>`}else if(type==='slots'){content=`<rect x="54" y="34" width="190" height="115" rx="9" fill="#80734f" stroke="#ccba85"/><rect x="64" y="44" width="170" height="94" rx="4" fill="#1f3025"/>${[0,1,2].map((n)=>`<rect x="${71+n*54}" y="51" width="47" height="80" rx="3" fill="#eee2bb"/><text x="${95+n*54}" y="106" text-anchor="middle" font-family="Georgia" font-size="43" fill="#855342">7</text>`).join('')}`}else if(type==='crash'){content='<path d="M42 142H254M42 142V28" stroke="#879681" stroke-width="1"/><path d="M45 139C110 138 170 100 238 32" fill="none" stroke="#bed49d" stroke-width="4"/><path d="M223 32L242 25L238 45" fill="none" stroke="#bed49d" stroke-width="4"/><text x="85" y="80" font-size="28" font-family="Georgia" fill="#ece4cf">2.48×</text>'}else if(type==='mines'){content=Array.from({length:12},(_,i)=>`<rect x="${77+i%4*36}" y="${40+Math.floor(i/4)*36}" width="29" height="29" rx="3" fill="${[2,5,8].includes(i)?'#c9d8a9':'#41614a'}" stroke="#91a582"/>${[2,5,8].includes(i)?`<path d="M${85+i%4*36} ${54+Math.floor(i/4)*36}l7-7 7 7-7 7Z" fill="#395b3e"/>`:''}`).join('')}else{content='<g transform="translate(99 37) rotate(-15 50 50)"><rect width="98" height="98" rx="16" fill="#dfdbc5" stroke="#f6efdb" stroke-width="3"/>'+[[25,25],[73,25],[49,49],[25,73],[73,73]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="8" fill="#426044"/>`).join('')+'</g>'}return `<svg viewBox="0 0 300 180" aria-hidden="true"><path d="M0 175L300 10M-20 130L250-10" stroke="#ffffff04" stroke-width="45"/>${content}</svg>`}
