function renderLobby(){ $('#main').innerHTML=`${heroScene()}<section id="catalog"><div class="intro"><div><span class="eyebrow">THE COLLECTION / 01—10</span><h2>Выбирай свой ритм.</h2><p>От первого хода до последней карты.</p></div><div class="search"><input id="search" aria-label="Поиск игр" placeholder="Найти игру" value="${esc(query)}"></div></div><div class="filters">${[['all','Все игры',10],['cards','Карточные',4],['table','Настольные',2],['slots','Слоты',1],['quick','Быстрые',3]].map(([id,title,n])=>`<button class="filter ${category===id?'active':''}" data-category="${id}">${title}<small>${n}</small></button>`).join('')}</div><div class="game-grid" id="gameGrid"></div></section><div class="notice"><span class="seal">◇</span><span><strong>Играйте с интересом, без риска.</strong> Здесь нет реальных денег. Все результаты и баланс рассчитываются на сервере.</span></div>`;renderCatalog();bindScene();$('#heroPlay').onclick=()=>$('#catalog').scrollIntoView({behavior:'smooth'});$('#search').oninput=e=>{query=e.target.value;renderCatalog()};document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));renderCatalog()})}
function renderCatalog(){$('#gameGrid').innerHTML=games.filter(g=>(category==='all'||g[3]===category)&&g[1].toLowerCase().includes(query.toLowerCase())).map((g,index)=>`<button style="--card-order:${index}" class="game-card feature-${g[0]}" data-game="${g[0]}"><div class="game-art">${art(g[0])}<span class="tag">${g[4]}</span></div><div class="card-info"><span class="arrow">↗</span><h3>${g[1]}</h3><p>${g[2]}</p></div></button>`).join('')||'<div class="empty">Таких игр пока нет. Попробуйте другое название.</div>';document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>openGame(b.dataset.game))}
function openGame(type){if(snapshot.game&&!snapshot.game.done&&snapshot.game.type!==type){toast('Сначала завершите текущую игру');type=snapshot.game.type}document.querySelectorAll('.control-panel input,.control-panel select').forEach(e=>{if(e.id)(uiPrefs[selectedGame]??={})[e.id]=e.value});selectedGame=type;selectedCards.clear();view='game';render();window.scrollTo(0,0)}
