const card=c=>{if(!c||c.hidden)return '<div class="playing-card back-card" aria-label="Закрытая карта"></div>';const suit=({S:'♠',H:'♥',D:'♦',C:'♣',spades:'♠',hearts:'♥',diamonds:'♦',clubs:'♣'})[c.suit]||c.suit||'♠',rank=({14:'A',13:'K',12:'Q',11:'J'})[c.rank]||c.rank;return `<div class="playing-card ${['♥','♦','H','D','hearts','diamonds'].includes(suit)||['H','D'].includes(c.suit)?'red':''}">${esc(rank)}<span class="suit">${esc(suit)}</span></div>`};
